SELECT

FROM TBL_ACCOUNTING_PERIOD
WHERE IS_DELETED = 0

    AND BOOK_ID = #{param.bookId}


    AND TENANT_ID = #{param.tenantId}


    AND PERIOD_ID = #{param.periodId}


    AND YEAR_NO = #{param.yearNo}


    AND MONTH_NO = #{param.monthNo}


    AND PERIOD_CODE LIKE '%' || #{param.periodCode} || '%'


    AND PERIOD_NAME LIKE '%' || #{param.periodName} || '%'


    AND PERIOD_STATUS = #{param.periodStatus}


    AND IS_CURRENT = #{param.isCurrent}


    AND START_DATE >= #{param.startDateBegin}


    AND START_DATE <= #{param.startDateEnd}


    AND END_DATE >= #{param.endDateBegin}


    AND END_DATE <= #{param.endDateEnd}


    AND CREATED_BY LIKE '%' || #{param.createdBy} || '%'

ORDER BY YEAR_NO DESC, MONTH_NO DESC

SELECT

FROM TBL_ACCOUNTING_PERIOD
WHERE IS_DELETED = 0
AND YEAR_NO = #{yearNo}
AND MONTH_NO = #{monthNo}
AND BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId}
FETCH FIRST 1 ROWS ONLY

mapper.update:
UPDATE TBL_ACCOUNTING_PERIOD
SET IS_CURRENT = 0
WHERE IS_DELETED = 0
AND BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId};

UPDATE TBL_ACCOUNTING_PERIOD
SET IS_CURRENT = 1,
    UPDATED_TIME = CURRENT_TIMESTAMP
WHERE IS_DELETED = 0
AND PERIOD_ID = #{periodId}
AND BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId}

