SELECT COUNT(1)
FROM TBL_ACCOUNTING_PERIOD
WHERE IS_DELETED = 0
AND PERIOD_STATUS = #{status}
AND BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId}

SELECT DISTINCT PERIOD_STATUS
FROM TBL_ACCOUNTING_PERIOD
WHERE IS_DELETED = 0
AND BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId}
ORDER BY PERIOD_STATUS
